// Package gentest holds the MCP tools of the generation test (spec/api/mcp-tools-generation-test.md): images and videos
// generated by models chosen one by one, outside any Project, compared side by side.
//
// A batch is models x prompts x count results. estimate_generation_test prices it; run_generation_test runs it only with the
// estimate_id and the total the caller was shown (the server prices the request again and refuses with "conflict" when it
// changed or is over the cap), and answers with a job_id: get_job reads it through the Probe of the job kind "gentest",
// get_generation_test shows every result. The files of the results are token URLs (download kind "gentest_file", no base64);
// input images are uploaded for the purpose "gentest_reference".
//
// A generation test writes no Take, no Cost Ledger row and no asset of a Project; import_generation_result is the one way a
// result enters a Project.
package gentest

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"path/filepath"

	"github.com/ousiassllc/mam/backend/internal/domain"
	"github.com/ousiassllc/mam/backend/internal/mcp/mcpkit"
	"github.com/ousiassllc/mam/backend/internal/service"
	"github.com/ousiassllc/mam/backend/internal/service/gentest"
	"github.com/ousiassllc/mam/backend/internal/service/gentest/gterr"
	"github.com/ousiassllc/mam/backend/internal/service/gentest/projectlink"
)

// Names of the job kind, the download kind and the upload purpose of this package.
const (
	KindGentest      = string(domain.JobGentest)
	KindGentestFile  = "gentest_file"
	PurposeReference = "gentest_reference"
)

// Register adds the tools, the Probe, the download kind and the upload purpose of this package. They answer "unavailable"
// when the app has no generation test.
func Register(r *mcpkit.Registrar, svc *service.Services) {
	h := handlers{svc: svc, registrar: r}
	r.Jobs.RegisterKind(KindGentest, h.probe)
	r.Files.RegisterDownload(KindGentestFile, h.file)
	r.Files.RegisterUpload(mcpkit.UploadSpec{
		Purpose:     PurposeReference,
		Description: "生成テストの入力画像（参照画像・動画の最初／最後のフレーム）。PNG・JPEG・WebP。応答の reference_id を estimate_generation_test / run_generation_test の references に {source: upload, id: reference_id} として渡す / Input picture of a generation test; pass the returned reference_id as {source: upload, id}.",
		MaxBytes:    gentest.MaxImageBytes,
		Handle:      h.uploadReference,
	})

	mcpkit.Read(r, "list_generation_models",
		"生成テストで選べるモデル（組み込みのクラウドモデルと、ローカル・登録した外部 ComfyUI・保存したワークフロー・ChatGPT サブスクのモデル）。能力・単価（priced / free / unknown）・使えない理由を含む。画像モデルは参照画像の使い方（reference_mode: edit / img2img、max_reference_images、reference_roles）と LoRA 対応（supports_lora）を持つ。loras は同梱 ComfyUI エンジンの LoRA 名の一覧 / Models a generation test can use, with capabilities, reference image support, LoRA support (loras lists the files), unit prices and why one is unavailable.",
		h.listModels)
	mcpkit.Read(r, "estimate_generation_test",
		"生成テスト（モデル × プロンプト × 本数の全組み合わせ）の本数と見積りを返す。モデルごとの内訳・警告・上限を含む。画像は references の role / strength、avoid_reference_pose、lora を付けられる（モデルが使えない分は警告）。run_generation_test に estimate_id と total_usd をそのまま渡す。単価が分からないモデル（unknown）は合計に入らない。translate_to_english（既定 true）のとき、日本語などの文を英語に訳す行（model が translate）が単価なしで入る / Price a batch without running it; the translation of non-English prompts is a line without a price.",
		h.estimate)
	mcpkit.Write(r, "run_generation_test",
		"生成テストを実行する。estimate_generation_test と同じ条件に、その estimate_id と confirmed_total_usd（= total_usd）を付ける。サーバーが見積りをやり直し、変わっていたり上限（gentest.max_cost_usd / max_items）を超えたら conflict で拒否する。translate_to_english（既定 true。画面と同じ）なら、日本語などのプロンプトを LLM で英語に訳してから送る（訳せなければ何も生成せず upstream）。job_id と batch_id を返す。Take・コスト台帳には入らない / Run a confirmed batch as a job; prompts that are not English are translated first unless translate_to_english is false.",
		h.run, mcpkit.OpenWorld())
	mcpkit.Read(r, "get_generation_test",
		"生成テストのバッチの進捗（状態ごとの件数）と、全結果（プロンプト・実際に送った文・シード・状態・失敗の理由・ファイルの有無）/ A batch with its progress and every result.",
		h.get)
	mcpkit.Write(r, "cancel_generation_test",
		"生成テストのバッチを取り消す。まだ始めていない分は取り消し、すでに呼んでいるものは終わるのを待つ / Cancel a batch: results not started are cancelled, calls in flight finish.",
		h.cancel)
	mcpkit.Read(r, "list_generation_results",
		"生成テストの履歴（新しい順）。モデル・種類・お気に入りで絞れる。合計コストも返す / The history of results, newest first.",
		h.listResults)
	mcpkit.Read(r, "get_generation_result",
		"生成テストの結果を 1 件取得する（設定・入力画像・取り込み先・ファイルのダウンロード URL）/ One result with its inputs, its imports and a download URL of the file.",
		h.getResult)
	mcpkit.Destroy(r, "delete_generation_result",
		"生成テストの結果とそのファイルを削除する。生成中のものは拒否される。バッチの最後の 1 件を消すとバッチも消える / Delete a result and its file; a result that has not finished is refused.",
		h.deleteResult)
	mcpkit.Write(r, "set_generation_favorite",
		"生成テストの結果のお気に入りを付ける・外す / Mark or unmark a result as a favorite.",
		h.setFavorite)
	mcpkit.Read(r, "list_generation_prompts",
		"生成テストのプロンプト履歴（同じプロンプト・ネガティブの組は 1 件にまとめる。使用回数・最後に使った日時つき）/ The prompt history.",
		h.listPrompts)
	mcpkit.Destroy(r, "delete_generation_prompt",
		"プロンプト履歴を 1 件削除する（結果の履歴には影響しない）/ Delete a prompt of the history.",
		h.deletePrompt)
	mcpkit.Write(r, "import_generation_result",
		"生成テストの結果（成功したもの）をプロジェクトに取り込む。参照（Reference Library。画像のみ。source=generated）かアセットとして、ファイルをプロジェクトの assets に複製する。参照にはさらに assign で Character の face/body・Product・Location のスロットへ割り当てられる / Import a succeeded result into a Project as a reference or an asset.",
		h.importResult)
}

type handlers struct {
	svc       *service.Services
	registrar *mcpkit.Registrar
}

func (h handlers) gt() (*gentest.Service, error) {
	if h.svc.Gentest == nil {
		return nil, &mcpkit.ToolError{Code: mcpkit.CodeUnavailable, Message: "生成テストはこのアプリでは使えません", Status: http.StatusServiceUnavailable}
	}
	return h.svc.Gentest, nil
}

// Input has no field.
type Input struct{}

// mapError turns the errors of the generation test into the codes a tool answers with: a refused input is validation, a
// changed estimate or a result that has not finished is conflict. An import whose assignment was refused says that the
// image is in the Library anyway.
func mapError(err error) error {
	if err == nil {
		return nil
	}
	var (
		invalid  *gterr.InvalidError
		conflict *gterr.ConflictError
		upstream *gterr.UpstreamError
		partial  *projectlink.PartialImportError
	)
	switch {
	case errors.As(err, &invalid):
		return &mcpkit.ToolError{Code: mcpkit.CodeValidation, Message: invalid.Message, Status: http.StatusUnprocessableEntity}
	case errors.As(err, &conflict):
		return &mcpkit.ToolError{Code: mcpkit.CodeConflict, Message: conflict.Message, Status: http.StatusConflict}
	case errors.As(err, &upstream):
		return &mcpkit.ToolError{Code: mcpkit.CodeUpstream, Message: upstream.Message, Status: http.StatusBadGateway}
	case errors.As(err, &partial):
		te := mcpkit.MapError(partial.Err)
		te.Message = "画像は取り込みましたが（asset_id " + partial.Outcome.AssetID + "、reference_id " + partial.Outcome.ReferenceItemID + "）、スロットへ割り当てられませんでした: " + te.Message
		return te
	case errors.Is(err, gterr.ErrNotFound):
		return &mcpkit.ToolError{Code: mcpkit.CodeNotFound, Message: "対象が見つかりません", Status: http.StatusNotFound}
	case errors.Is(err, gterr.ErrUnavailable):
		return &mcpkit.ToolError{Code: mcpkit.CodeUnavailable, Message: "生成テストはこのアプリでは使えません", Status: http.StatusServiceUnavailable}
	}
	return mcpkit.MapError(err)
}

// probe reads a gentest job from the results of its batch (counted: nothing is stored apart from them).
func (h handlers) probe(ctx context.Context, job mcpkit.JobInfo) (mcpkit.Progress, error) {
	g, err := h.gt()
	if err != nil {
		return mcpkit.Progress{}, err
	}
	b, err := g.BatchOfJob(ctx, job.ID, false)
	if errors.Is(err, gterr.ErrNotFound) {
		return mcpkit.Progress{State: mcpkit.JobCancelled, Message: "バッチは削除されました"}, nil
	}
	if err != nil {
		return mcpkit.Progress{}, mapError(err)
	}
	return mcpkit.Progress{
		State: jobState(b.State), Done: b.Done, Total: b.Total, Error: b.Error,
		Message: progressMessage(b),
		Result: map[string]any{
			"batch_id": b.BatchID, "succeeded": b.Succeeded, "failed": b.Failed, "cancelled": b.Cancelled,
			"next": "get_generation_test で全結果を見る",
		},
	}, nil
}

func jobState(state string) mcpkit.JobState {
	switch state {
	case gentest.StateQueued:
		return mcpkit.JobQueued
	case gentest.StateSucceeded:
		return mcpkit.JobSucceeded
	case gentest.StateFailed:
		return mcpkit.JobFailed
	case gentest.StateCancelled:
		return mcpkit.JobCancelled
	}
	return mcpkit.JobRunning
}

func progressMessage(b gentest.BatchStatus) string {
	return fmt.Sprintf("%d / %d 件が終わりました（成功 %d、失敗 %d、取り消し %d）", b.Done, b.Total, b.Succeeded, b.Failed, b.Cancelled)
}

// file is the download kind: the file of a succeeded result (the resource id is the result id).
func (h handlers) file(ctx context.Context, id string) (mcpkit.DownloadFile, error) {
	g, err := h.gt()
	if err != nil {
		return mcpkit.DownloadFile{}, err
	}
	f, err := g.ResultFile(ctx, id)
	if err != nil {
		return mcpkit.DownloadFile{}, mapError(err)
	}
	return mcpkit.DownloadFile{Name: id + filepath.Ext(f.Path), ContentType: f.Mime, Path: f.Path}, nil
}

// uploadReference stores the picture for the batch that names it.
func (h handlers) uploadReference(_ context.Context, in mcpkit.UploadInput) (any, error) {
	g, err := h.gt()
	if err != nil {
		return nil, err
	}
	f, err := in.Header.Open()
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()
	data, err := io.ReadAll(io.LimitReader(f, gentest.MaxImageBytes+1))
	if err != nil {
		return nil, err
	}
	id, mime, err := g.StageReference(data)
	if err != nil {
		return nil, mapError(err)
	}
	return map[string]any{"reference_id": id, "mime_type": mime}, nil
}
